create or replace function public.business_manage_location(p_business_id uuid,p_location_id uuid,p_action text,p_name text default null,p_address text default null,p_city text default null,p_state text default null,p_is_active boolean default null) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$ declare v jsonb; begin if not exists(select 1 from business_members bm where bm.business_id=p_business_id and bm.user_id=auth.uid() and lower(bm.role) in('owner','admin')) then raise exception 'Admin access required'; end if; if p_action='create' then insert into locations(business_id,name,address,city,state,is_active) values(p_business_id,coalesce(p_name,'New Location'),p_address,p_city,p_state,coalesce(p_is_active,true)) returning to_jsonb(locations.*) into v; elsif p_action='update' then update locations set name=coalesce(p_name,name),address=coalesce(p_address,address),city=coalesce(p_city,city),state=coalesce(p_state,state),is_active=coalesce(p_is_active,is_active) where id=p_location_id and business_id=p_business_id returning to_jsonb(locations.*) into v; elsif p_action='deactivate' then update locations set is_active=false where id=p_location_id and business_id=p_business_id returning to_jsonb(locations.*) into v; else raise exception 'Unknown location action'; end if; if v is null then raise exception 'Location not found'; end if; return v; end $$;
create or replace function public.business_manage_promotion(p_business_id uuid,p_promotion_id uuid,p_action text,p_title text default null,p_description text default null,p_discount numeric default null,p_active boolean default null,p_starts_at timestamptz default null,p_ends_at timestamptz default null) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$ declare v jsonb; begin if not exists(select 1 from business_members bm where bm.business_id=p_business_id and bm.user_id=auth.uid() and lower(bm.role) in('owner','admin')) then raise exception 'Admin access required'; end if; if p_action='create' then insert into promotions(business_id,title,description,discount,active,starts_at,ends_at) values(p_business_id,coalesce(p_title,'New Promotion'),p_description,p_discount,coalesce(p_active,false),p_starts_at,p_ends_at) returning to_jsonb(promotions.*) into v; elsif p_action='update' then update promotions set title=coalesce(p_title,title),description=coalesce(p_description,description),discount=coalesce(p_discount,discount),active=coalesce(p_active,active),starts_at=coalesce(p_starts_at,starts_at),ends_at=coalesce(p_ends_at,ends_at) where id=p_promotion_id and business_id=p_business_id returning to_jsonb(promotions.*) into v; elsif p_action='deactivate' then update promotions set active=false where id=p_promotion_id and business_id=p_business_id returning to_jsonb(promotions.*) into v; else raise exception 'Unknown promotion action'; end if; if v is null then raise exception 'Promotion not found'; end if; return v; end $$;
create or replace function public.business_manage_event(p_business_id uuid,p_event_id uuid,p_action text,p_title text default null,p_description text default null,p_event_date date default null,p_event_time text default null) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$ declare v jsonb; begin if not exists(select 1 from business_members bm where bm.business_id=p_business_id and bm.user_id=auth.uid() and lower(bm.role) in('owner','admin')) then raise exception 'Admin access required'; end if; if p_action='create' then insert into business_events(business_id,title,description,event_date,event_time) values(p_business_id,coalesce(p_title,'New Event'),p_description,p_event_date,p_event_time) returning to_jsonb(business_events.*) into v; elsif p_action='update' then update business_events set title=coalesce(p_title,title),description=coalesce(p_description,description),event_date=coalesce(p_event_date,event_date),event_time=coalesce(p_event_time,event_time) where id=p_event_id and business_id=p_business_id returning to_jsonb(business_events.*) into v; elsif p_action='delete' then delete from business_events where id=p_event_id and business_id=p_business_id returning to_jsonb(business_events.*) into v; else raise exception 'Unknown event action'; end if; if v is null then raise exception 'Event not found'; end if; return v; end $$;
create or replace function public.business_manage_campaign(p_business_id uuid,p_campaign_id uuid,p_action text,p_name text default null,p_campaign_type text default null,p_goal text default null,p_status text default null) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$ declare v jsonb; begin if not exists(select 1 from business_members bm where bm.business_id=p_business_id and bm.user_id=auth.uid() and lower(bm.role) in('owner','admin')) then raise exception 'Admin access required'; end if; if p_action in('create','update') then if p_action='create' then insert into campaigns(business_id,name,campaign_type,goal,status) values(p_business_id,coalesce(p_name,'New Campaign'),p_campaign_type,p_goal,coalesce(p_status,'draft')) returning to_jsonb(campaigns.*) into v; else update campaigns set name=coalesce(p_name,name),campaign_type=coalesce(p_campaign_type,campaign_type),goal=coalesce(p_goal,goal),status=coalesce(p_status,status) where id=p_campaign_id and business_id=p_business_id returning to_jsonb(campaigns.*) into v; end if; elsif p_action='pause' then update campaigns set status='paused' where id=p_campaign_id and business_id=p_business_id returning to_jsonb(campaigns.*) into v; elsif p_action='activate' then update campaigns set status='active' where id=p_campaign_id and business_id=p_business_id returning to_jsonb(campaigns.*) into v; else raise exception 'Unknown campaign action'; end if; if v is null then raise exception 'Campaign not found'; end if; return v; end $$;
